using UnityEngine;using TMPro;public class EnemyChanger : MonoBehaviour{    [SerializeField] private TMP_InputField inputField;

    private Enemy[] allEnemies;    private void Start()    {        allEnemies = FindObjectsByType<Enemy>(FindObjectsSortMode.None);    }    public void FilterByHealth()    {        if (int.TryParse(inputField.text, out int minHealth))        {            foreach (Enemy enemy in allEnemies)            {                enemy.gameObject.SetActive(enemy.Health > minHealth);            }        }    }    public void FilterByLevel()    {        if (int.TryParse(inputField.text, out int targetLevel))        {            foreach (Enemy enemy in allEnemies)            {                enemy.gameObject.SetActive(enemy.Level == targetLevel);            }        }    }    public void ResetFilters()    {        foreach (Enemy enemy in allEnemies)        {            enemy.gameObject.SetActive(true);        }    }    public void UpgradeToBoss()    {        string targetName = inputField.text;        if (string.IsNullOrEmpty(targetName)) return;        foreach (Enemy enemy in allEnemies)        {            if (enemy.UnitName == targetName)            {                enemy.MakeBoss();            }        }    }}